-- Новые вопросы тем 13–16 (близко к лекциям и практике курса DBA1) с пояснениями к каждому варианту.
-- Повторный запуск безопасен: вопрос с тем же текстом не добавляется второй раз.

BEGIN;

INSERT INTO questions (category_id, question_text, options, correct_answer, explanation, option_notes)
SELECT n.* FROM (
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Какой атрибут нужен роли, чтобы создавать другие роли?', '{"A":"CREATEDB","B":"CREATEROLE","C":"LOGIN","D":"REPLICATION"}'::jsonb, 'B', 'Атрибуты задают общие особенности роли, не связанные с конкретными объектами. Суперпользователь может всё и без них.', '{"A":"Даёт право создавать базы данных, а не роли.","B":"Этот атрибут даёт право создавать роли.","C":"Разрешает подключаться к серверу, но не создавать роли.","D":"Нужен для подключения по протоколу репликации."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Когда сервер в Linux начинает применять изменения, внесённые в pg_hba.conf?', '{"A":"После следующей контрольной точки","B":"Только после полной остановки и запуска сервера","C":"Сразу после сохранения файла","D":"После перечитывания конфигурации, например функцией pg_reload_conf()"}'::jsonb, 'D', 'Перечитать конфигурацию можно и командой reload утилиты управления. В Windows изменения применяются к новым подключениям без перечитывания.', '{"A":"Контрольная точка к конфигурации доступа отношения не имеет.","B":"Перезапуск не нужен, достаточно перечитать конфигурацию.","C":"Сервер не отслеживает изменения файла сам, его нужно перечитать.","D":"Как и для параметров postgresql.conf, не требующих перезапуска, изменения вступают в силу после перечитывания."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Как следует располагать записи в pg_hba.conf?', '{"A":"В алфавитном порядке имён баз данных","B":"От общих правил к частным","C":"От частных правил к общим","D":"Порядок не имеет значения"}'::jsonb, 'C', 'Если не подошла ни одна запись, доступ запрещается.', '{"A":"Порядок задаёт приоритет записей, а не алфавит.","B":"Общая запись в начале файла подошла бы всем подключениям, и частные не сработали бы.","C":"Используется первая подходящая запись, поэтому общее правило выше частного перекрыло бы его.","D":"Файл просматривается сверху вниз, и порядок определяет результат."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Где в кластере хранится хеш пароля роли?', '{"A":"В файле ~/.pgpass на сервере","B":"В файле postgresql.conf","C":"В таблице системного каталога pg_authid","D":"В файле pg_hba.conf"}'::jsonb, 'C', 'Если для роли пароль не задан, а в pg_hba.conf указан парольный метод, в доступе будет отказано.', '{"A":"Этот файл находится на стороне клиента и нужен для автоматического ввода пароля.","B":"В нём хранятся параметры конфигурации, пароли ролей там не задаются.","C":"Это общая таблица каталога; пароль хранится в виде хеша.","D":"В нём описаны правила подключения, но не пароли."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Какая привилегия нужна, чтобы роль могла создавать временные таблицы в базе данных?', '{"A":"CREATE на схему public","B":"USAGE на табличное пространство","C":"TEMPORARY на базу данных","D":"CONNECT на базу данных"}'::jsonb, 'C', 'Привилегия CREATE на базу данных разрешает создавать в ней схемы.', '{"A":"Временные таблицы создаются в отдельной временной схеме, а не в public.","B":"Для табличных пространств такой привилегии нет, есть только CREATE.","C":"Имя схемы для временных объектов заранее неизвестно, поэтому привилегия вынесена на уровень базы.","D":"Разрешает подключение к базе, но не создание временных таблиц."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Роль bob с атрибутом NOINHERIT включили в роль dba командой GRANT dba TO bob. Как bob может воспользоваться привилегиями dba?', '{"A":"Только после смены атрибута LOGIN","B":"Никак: роль с NOINHERIT нельзя включать в другие роли","C":"Только после явного переключения командой SET ROLE dba","D":"Автоматически, как любая включённая роль"}'::jsonb, 'C', 'В PostgreSQL 16 атрибут NOINHERIT задаёт значение по умолчанию для параметра INHERIT новых членств; по умолчанию роль наследует привилегии включающей роли.', '{"A":"LOGIN определяет возможность подключения, а не наследование.","B":"Включение допускается, меняется лишь способ использования привилегий.","C":"Автоматически привилегии dba не применяются, а переключение разрешено.","D":"Так было бы без NOINHERIT."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Почему недостаточно один раз отозвать у public привилегию EXECUTE на все подпрограммы?', '{"A":"Привилегию EXECUTE у public отозвать нельзя","B":"После отзыва привилегия возвращается при перезапуске сервера","C":"Для каждой новой подпрограммы public снова получает EXECUTE автоматически","D":"Подпрограммы не подчиняются системе привилегий"}'::jsonb, 'C', 'Для этого служит команда ALTER DEFAULT PRIVILEGES.', '{"A":"Отозвать можно, но результат касается только существующих подпрограмм.","B":"Перезапуск привилегии не меняет.","C":"Остановить это можно механизмом привилегий по умолчанию.","D":"Для них определена привилегия EXECUTE."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Что проверяется после того, как в pg_hba.conf найдена подходящая запись?', '{"A":"Наличие привилегии CONNECT на базу данных","B":"Наличие привилегии SELECT на таблицы базы","C":"Наличие у роли атрибута LOGIN","D":"Успешность аутентификации методом из этой записи"}'::jsonb, 'ACD', 'После найденной записи другие строки файла уже не рассматриваются.', '{"A":"Проверяется вместе с остальным до допуска к базе.","B":"Права на таблицы проверяются позже, при обращении к ним.","C":"Без него подключиться нельзя.","D":"Метод задан в записи."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Какие привилегии определены для последовательностей?', '{"A":"SELECT","B":"USAGE","C":"EXECUTE","D":"UPDATE"}'::jsonb, 'ABD', 'Выбирая привилегии, можно разрешить или запретить доступ к управляющим функциям последовательности.', '{"A":"Разрешает currval.","B":"Разрешает currval и nextval.","C":"Эта привилегия относится к функциям и процедурам.","D":"Разрешает nextval и setval."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Какие из перечисленных ролей входят в число предопределённых в PostgreSQL 16?', '{"A":"pg_admin","B":"pg_superuser","C":"pg_monitor","D":"pg_write_all_data"}'::jsonb, 'CD', 'Список ролей, включая предопределённые, показывает команда psql \duS.', '{"A":"Такой предопределённой роли нет.","B":"Такой предопределённой роли нет; суперпользователь определяется атрибутом SUPERUSER.","C":"Роль для мониторинга, объединяет доступ к статистике и параметрам.","D":"Даёт право изменять данные во всех таблицах."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Допишите строку pg_hba.conf, чтобы безусловно запретить роли mallory подключаться с любых адресов:
```
# TYPE  DATABASE  USER     ADDRESS  METHOD
host    all       mallory  all      ___
```', '{"A":"peer","B":"reject","C":"md5","D":"trust"}'::jsonb, 'B', 'Метод reject безусловно запрещает подключение.', '{"A":"Спрашивает имя пользователя у операционной системы и работает только для локальных подключений.","B":"Метод безусловно отказывает в подключении. Запись должна стоять выше общих правил.","C":"Запрашивает пароль, а не запрещает подключение.","D":"Безусловно разрешает подключение."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Допишите строку pg_hba.conf, чтобы метод peer использовал отображение имён stmap из pg_ident.conf:
```
# TYPE  DATABASE  USER       METHOD
local   all       alice,bob  peer ___
```', '{"A":"usermap=stmap","B":"mapping=stmap","C":"map=stmap","D":"ident=stmap"}'::jsonb, 'C', 'Отображение связывает имя пользователя ОС с именем роли в базе данных; одно отображение можно использовать для разных ролей.', '{"A":"Такого параметра нет.","B":"Такого параметра нет.","C":"Параметр map указывает имя отображения из pg_ident.conf.","D":"Такого параметра нет."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '13.'), 'Допишите команду, чтобы отозвать у public выданное по умолчанию право подключаться к базе appdb:
```
REVOKE ___ ON DATABASE appdb FROM public;
```', '{"A":"USAGE","B":"CONNECT","C":"LOGIN","D":"EXECUTE"}'::jsonb, 'B', 'Подключение к любой базе разрешено public по умолчанию.', '{"A":"Для баз данных такой привилегии нет, USAGE бывает у схем и последовательностей.","B":"Именно эта привилегия разрешает подключение к базе, по умолчанию она есть у public. Ролям, получившим её иначе, и суперпользователям подключение не запрещается.","C":"LOGIN — атрибут роли, а не привилегия на объект.","D":"Эта привилегия относится к подпрограммам."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'На какой момент можно восстановить данные из обычной логической копии?', '{"A":"Только на момент, когда копия была снята","B":"На момент последней контрольной точки","C":"На момент сбоя сервера","D":"На любой момент после снятия копии"}'::jsonb, 'A', 'Это один из недостатков логической копии наряду с невысокой скоростью.', '{"A":"Логическая копия не содержит журнала, по которому можно было бы продвинуться дальше.","B":"Контрольные точки к логической копии отношения не имеют.","C":"Это возможно только при непрерывной архивации журналов.","D":"Для этого нужен архив журналов предзаписи, то есть физическое копирование."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Что позволяет ускорить копирование и восстановление большой базы данных утилитами pg_dump и pg_restore?', '{"A":"Использование утилиты pg_dumpall","B":"Отключение журнала предзаписи","C":"Копия в специальном формате с оглавлением и параллельное выполнение","D":"Выполнение скрипта в psql в нескольких сеансах"}'::jsonb, 'C', 'При восстановлении pg_restore позволяет также ограничить набор объектов.', '{"A":"Она выдаёт только скрипт для psql и параллельную выгрузку не поддерживает.","B":"Это не штатный способ ускорения восстановления.","C":"Восстанавливать параллельно можно копии в форматах custom и directory, выгружать параллельно — в формате directory.","D":"Простой SQL-скрипт выполняется последовательно."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Что делает pg_basebackup в самом начале работы?', '{"A":"Выполняет контрольную точку","B":"Блокирует все таблицы кластера","C":"Удаляет старые сегменты журнала","D":"Останавливает сервер"}'::jsonb, 'A', 'Подключение выполняется по протоколу репликации.', '{"A":"После этого копируются файлы кластера.","B":"Работа сервера не блокируется.","C":"Сегменты WAL, созданные за время копирования, наоборот, сохраняются.","D":"Утилита делает горячую копию на работающем сервере."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Какие журналы предзаписи нужны, чтобы восстановить горячую копию файлов кластера?', '{"A":"Как минимум журналы за время копирования файлов","B":"Только последний сегмент журнала","C":"Журналы не нужны, копия всегда согласована","D":"Только журналы после окончания копирования"}'::jsonb, 'A', 'Поэтому pg_basebackup сохраняет все сегменты WAL, созданные за время копирования.', '{"A":"Копия получается несогласованной, и согласованность восстанавливается по журналам.","B":"Нужны все записи за время копирования.","C":"Так бывает только при копировании остановленного сервера.","D":"Нужны записи за время копирования, начиная с контрольной точки."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Зачем при резервном копировании по протоколу репликации используется слот репликации?', '{"A":"Чтобы сжимать журнальные записи","B":"Чтобы ускорить копирование файлов данных","C":"Чтобы разрешить подключение без роли с атрибутом REPLICATION","D":"Чтобы сервер не удалил сегменты WAL, пока клиент не получил их"}'::jsonb, 'D', 'Слот помнит, какая запись была считана последней.', '{"A":"Сжатие не его задача.","B":"Скорость копирования слот не меняет.","C":"Роль с этим атрибутом (или суперпользователь) нужна в любом случае.","D":"Слот помнит, до какой позиции клиент получил журнал, и удерживает ещё не полученные сегменты."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Когда сегмент журнала попадает в файловый архив?', '{"A":"Только при остановке сервера","B":"Сразу при записи каждой журнальной записи","C":"После того как сервер переключится на запись в следующий сегмент","D":"При каждой контрольной точке"}'::jsonb, 'C', 'Для архивации запускается команда из параметра archive_command. Переключиться на новый сегмент сервер может и до заполнения: по archive_timeout или функцией pg_switch_wal().', '{"A":"Архивация идёт непрерывно, по мере переключения сегментов.","B":"Так работает потоковый архив, а не файловый.","C":"Поэтому текущий сегмент в архив не попадает и возникают задержки.","D":"Момент определяется переключением сегмента, а не контрольной точкой."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Чем потоковый архив журналов, который ведёт pg_receivewal, отличается от файлового?', '{"A":"Записи пишутся в архив постоянно, не дожидаясь заполнения сегмента","B":"Он работает под управлением сервера и не требует внешних утилит","C":"Он не требует подключения к серверу","D":"Он хранит только заполненные сегменты"}'::jsonb, 'A', 'Утилиту нужно запускать и перезапускать средствами операционной системы.', '{"A":"Поэтому задержки минимальны.","B":"Это описание файлового архива, а pg_receivewal — отдельная утилита.","C":"Утилита подключается по протоколу репликации.","D":"Незаполненный сегмент хранится тоже, с суффиксом .partial."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Какой суффикс имеет файл незаполненного сегмента, который сейчас пишет pg_receivewal?', '{"A":".backup","B":".wip","C":".tmp","D":".partial"}'::jsonb, 'D', 'При восстановлении вместе с обычными сегментами можно использовать и недозаписанный файл.', '{"A":"Так называют файл с описанием резервной копии, а не недописанный сегмент.","B":"Такого суффикса утилита не использует.","C":"Такого суффикса утилита не использует.","D":"После заполнения сегмента файл переименовывается."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Что задаёт параметр restore_command при восстановлении из архива?', '{"A":"Команду, которая копирует нужный сегмент WAL из архива в каталог сервера","B":"Команду перезапуска сервера после восстановления","C":"Команду, которая создаёт базовую копию","D":"Целевую точку восстановления"}'::jsonb, 'A', 'Сервер вызывает её, когда нужного сегмента нет в каталоге pg_wal.', '{"A":"Это команда, обратная archive_command.","B":"Параметр не связан с запуском сервера.","C":"Базовую копию создаёт pg_basebackup.","D":"Целевая точка задаётся отдельными параметрами."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Какие потери возможны при восстановлении из архива, который наполнялся командой archive_command?', '{"A":"Только записи последней минуты","B":"Записи из незаполненного сегмента WAL, который не попал в архив","C":"Потерь не бывает","D":"Все записи после последней базовой копии"}'::jsonb, 'B', 'Такой сегмент можно скопировать в каталог pg_wal вручную, если он ещё доступен. При сбоях архивации таких сегментов может оказаться несколько.', '{"A":"Фиксированного срока нет: теряется то, что не успело попасть в архив.","B":"Если его нельзя скопировать вручную, он теряется.","C":"Последний незаполненный сегмент остаётся вне архива.","D":"Заархивированные сегменты применяются, теряется только то, что в архив не попало."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Что нужно подготовить заранее, чтобы восстановить базу данных из копии pg_dump, сделанной без ключа --create, на новом кластере?', '{"A":"Пустую базу данных, созданную из шаблона template0","B":"Табличные пространства","C":"Роли, которым принадлежат объекты базы","D":"Таблицы и индексы базы"}'::jsonb, 'ABC', 'После восстановления имеет смысл выполнить ANALYZE, чтобы собрать статистику.', '{"A":"Изменения template1 попали бы в копию повторно.","B":"Они тоже относятся ко всему кластеру.","C":"Роли относятся ко всему кластеру и в копию базы не входят.","D":"Их создаёт сама процедура восстановления."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Что верно для физической резервной копии?', '{"A":"Можно восстановить одну базу данных из кластера","B":"При наличии архива журналов можно восстановить кластер на нужный момент времени","C":"Восстановление выполняется быстрее, чем из логической копии","D":"Копию можно развернуть на другой основной версии PostgreSQL"}'::jsonb, 'BC', 'Для физической копии используют утилиту pg_basebackup.', '{"A":"Восстанавливается только весь кластер.","B":"Журналы применяются до целевой точки.","C":"Файлы копируются как есть, индексы строить не нужно.","D":"Нужна та же основная версия и та же архитектура."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Допишите команду archive_command, чтобы сегмент копировался в архив под своим именем:
```
archive_command = ''cp %p /mnt/archive/___''
```', '{"A":"%p","B":"%%","C":"%f","D":"%n"}'::jsonb, 'C', 'Если команда завершается с нулевым статусом, сегмент считается заархивированным.', '{"A":"Подставляется путь к сегменту относительно каталога данных (pg_wal/…), и в архиве получился бы неверный путь.","B":"Это просто символ процента.","C":"Подставляется имя файла сегмента без пути.","D":"Такой подстановки в команде нет."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Допишите команду COPY, чтобы выгрузить в файл только счета с положительным балансом:
```
COPY (SELECT * FROM accounts WHERE balance > 0) ___ ''/tmp/accounts.csv'' WITH (FORMAT csv);
```', '{"A":"TO","B":"FROM","C":"OUT","D":"INTO"}'::jsonb, 'A', 'COPY позволяет выгрузить не только таблицу, но и результат запроса.', '{"A":"COPY ... TO выводит данные в файл, поток или программу.","B":"COPY ... FROM загружает данные в таблицу.","C":"Такого ключевого слова в COPY нет.","D":"Такого ключевого слова в COPY нет."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'Почему при wal_level = minimal физическая репликация невозможна?', '{"A":"Реплика не может подключиться к серверу по сети","B":"На этом уровне журнал предзаписи отключён полностью","C":"На этом уровне нельзя создавать слоты репликации","D":"Часть изменений сразу записывается на диск и не попадает в журнал"}'::jsonb, 'D', 'Начиная с версии 10 по умолчанию используется уровень replica.', '{"A":"Причина в составе информации в журнале, а не в сети.","B":"Журнал ведётся, он нужен для восстановления после сбоя.","C":"Невозможность репликации объясняется составом журнала.","D":"Реплике нужны все данные из журнала, а на этом уровне их недостаточно."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'Как настраивают реплику для долгих аналитических запросов?', '{"A":"Реплика откладывает применение журнальных записей, которые конфликтуют с запросами","B":"Включают синхронный режим фиксации","C":"Переводят основной сервер на wal_level = minimal","D":"На реплике отключают приём журнальных записей"}'::jsonb, 'A', 'Альтернатива для коротких OLTP-запросов — обратная связь реплики с основным сервером.', '{"A":"Данные на ней могут отставать, для отчётов это обычно не страшно.","B":"Он нужен для надёжности хранения, а не для отчётов.","C":"При этом репликация перестанет работать.","D":"Тогда реплика перестанет получать данные."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'Гарантируется ли согласованность данных, если приложение читает то с основного сервера, то с реплик?', '{"A":"Да, при синхронной репликации","B":"Нет, даже при синхронной репликации можно получить устаревшие данные или такие, которых ещё не видно на основном сервере","C":"Да, но только для каскадной репликации","D":"Да, если включена обратная связь hot_standby_feedback"}'::jsonb, 'B', 'Для автоматического распределения запросов нужны внешние средства, например балансировщики.', '{"A":"Согласованность между серверами не гарантируется даже в этом случае.","B":"Согласованное чтение гарантировано только при работе с одним сервером.","C":"Для каскада это тем более не гарантируется.","D":"Обратная связь влияет на очистку и не обеспечивает согласованность чтения."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'От каких реплик каскада основной сервер получает обратную связь hot_standby_feedback, если она включена?', '{"A":"Только от первой реплики в цепочке","B":"Ни от одной, в каскаде она не поддерживается","C":"Только от последней реплики в цепочке","D":"От всех реплик каскада"}'::jsonb, 'D', 'Чем дальше реплика от основного сервера, тем больше запаздывание.', '{"A":"Обратная связь поступает от всех реплик.","B":"Каскадная синхронная репликация не поддерживается, а обратная связь работает.","C":"Обратная связь поступает от всех реплик.","D":"Хотя синхронизироваться основной сервер может только с непосредственно подключённой репликой."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'Для чего нужна реплика с отложенным применением журнальных записей?', '{"A":"Чтобы посмотреть данные на момент в прошлом и восстановиться после ошибки пользователя","B":"Чтобы ускорить фиксацию транзакций на основном сервере","C":"Чтобы разгрузить основной сервер от записи","D":"Чтобы заменить архив журналов предзаписи"}'::jsonb, 'A', 'В PostgreSQL нет готового способа построить снимок данных на произвольный момент в прошлом.', '{"A":"Реплика применяет изменения с заданной задержкой, поэтому они становятся видны позже.","B":"Ускорить фиксацию она не может, а синхронная реплика при synchronous_commit = remote_apply её даже замедлит.","C":"Записи все равно выполняются только на основном сервере.","D":"Она облегчает восстановление на момент в прошлом, но не заменяет архив."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'Из чего создают физическую реплику?', '{"A":"Из физической резервной копии основного сервера","B":"Из пустого кластера после initdb","C":"Из логической копии, сделанной pg_dump","D":"Командой CREATE SUBSCRIPTION"}'::jsonb, 'A', 'Реплика постоянно применяет журнальные записи, пришедшие с основного сервера.', '{"A":"Ведомый сервер затем работает в режиме постоянного восстановления.","B":"У нового кластера другой идентификатор системы, и журнал основного сервера к нему не применить.","C":"Логическая копия не годится, так как нужна двоичная совместимость.","D":"Эта команда относится к логической репликации."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'Что делает реплика с настроенным чтением из архива (restore_command), если очередную журнальную запись не удаётся получить по протоколу репликации?', '{"A":"Переходит в режим основного сервера","B":"Пытается прочитать соответствующий файл из архива сегментов WAL","C":"Останавливается навсегда","D":"Запрашивает у клиента повторить запрос"}'::jsonb, 'B', 'Для файловой репликации нужно настроенное непрерывное архивирование.', '{"A":"Для этого нужно переключение, а не потеря связи.","B":"Файловую репликацию используют как дополнение к потоковой.","C":"Она продолжает попытки получить запись, в том числе из архива.","D":"Клиенты в этом не участвуют."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'При synchronous_commit = on и заданной синхронной реплике реплику остановили. Что будет с фиксацией изменяющих транзакций на основном сервере?', '{"A":"Основной сервер автоматически переключается в асинхронный режим","B":"Транзакции откатываются с ошибкой","C":"Транзакции фиксируются, как обычно","D":"Фиксация не завершается, пока реплика не подтвердит, что журнальные записи сохранены"}'::jsonb, 'D', 'Синхронный режим повышает надёжность, но замедляет работу.', '{"A":"Автоматического переключения нет.","B":"Фиксация ждёт подтверждения, а не откатывается.","C":"Это поведение асинхронного режима.","D":"Именно так проверяют синхронный режим в практике курса."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'Какой параметр ограничивает число одновременных подключений по протоколу репликации?', '{"A":"max_wal_senders","B":"max_connections","C":"max_replication_slots","D":"wal_keep_size"}'::jsonb, 'A', 'Настройки по умолчанию достаточны для локального подключения.', '{"A":"Он задаёт число одновременно работающих процессов wal_sender.","B":"Ограничивает общее число обычных подключений.","C":"Ограничивает число слотов репликации, а не подключений.","D":"Задаёт минимальный объём прошлых сегментов журнала, которые сервер сохраняет."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'Что нужно, чтобы запросы распределялись между репликами автоматически?', '{"A":"Включить параметр hot_standby","B":"Внешние средства, например балансировщики","C":"Переключить wal_level на logical","D":"Достаточно настроить физическую репликацию"}'::jsonb, 'B', 'Распределение нагрузки по чтению — одна из типичных задач реплик.', '{"A":"Он лишь разрешает запросы на реплике.","B":"Репликация предоставляет только базовый механизм.","C":"Это не связано с распределением запросов.","D":"Сама репликация распределением запросов не занимается."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'Какие два источника журнальных записей могут конфликтовать с запросом на реплике?', '{"A":"Контрольные точки основного сервера","B":"Исключительные блокировки на основном сервере","C":"Подключение новых клиентов к основному серверу","D":"Очистка, удаляющая версии строк, нужные запросу"}'::jsonb, 'BD', 'Поэтому такую реплику настраивают, чтобы она откладывала применение конфликтующих записей.', '{"A":"Контрольные точки с запросами не конфликтуют.","B":"Например, блокировка ACCESS EXCLUSIVE таблицы, которую читает запрос на реплике.","C":"Само по себе оно в журнале не отражается.","D":"Основному серверу они уже не нужны."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'Для решения каких задач применяют физическую репликацию?', '{"A":"Выполнение долгих аналитических запросов на реплике","B":"Обновление основной версии без прерывания обслуживания","C":"Репликация только отдельных таблиц","D":"Распределение нагрузки по чтению между репликами"}'::jsonb, 'AD', 'Физическая репликация создаёт точную копию всего кластера.', '{"A":"Реплика разгружает основной сервер.","B":"Для этого нет двоичной совместимости; применяют логическую репликацию.","C":"Физически реплицируется только весь кластер.","D":"Для коротких OLTP-запросов."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '15.'), 'Допишите строку pg_hba.conf на основном сервере, чтобы разрешить роли repl подключения физической репликации:
