```', '{"A":"origin","B":"two_phase","C":"binary","D":"streaming"}'::jsonb, 'A', 'Начальную синхронизацию в такой схеме отключают параметром copy_data = false.', '{"A":"Значение none оставляет только изменения, которые не пришли из другого источника репликации.","B":"Логическое значение, относится к двухфазной фиксации.","C":"Логическое значение, переключает двоичный формат передачи.","D":"Принимает значения off, on и parallel и относится к передаче долгих транзакций."}'::jsonb
) AS n(category_id, question_text, options, correct_answer, explanation, option_notes)
WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.question_text = n.question_text);

DO $check$
DECLARE n integer;
BEGIN
    SELECT count(*) INTO n FROM questions WHERE option_notes IS NOT NULL AND category_id IN (SELECT id FROM categories WHERE left(name, 3) IN ('13.', '14.', '15.', '16.'));
    IF n < 53 THEN
        RAISE EXCEPTION 'Ожидалось не меньше 53 вопросов с пояснениями в темах 13–16, найдено %', n;
    END IF;
END
$check$;

COMMIT;
